def process(swarm_2014_data) -> pd.DataFrame:
    peak_density = swarm_2014_data['Orbit Mean Density (kg/m^3)'].max()
    return pd.DataFrame({'peak_density_2014': [peak_density]})

def process(swarm_2018_data) -> pd.DataFrame:
    peak_density = swarm_2018_data['Orbit Mean Density (kg/m^3)'].max()
    return pd.DataFrame({'peak_density_2018': [peak_density]})

def process(peak_2014, peak_2018) -> pd.DataFrame:
    ratio = peak_2014['peak_density_2014'].values[0] / peak_2018['peak_density_2018'].values[0]
    return pd.DataFrame({'ratio': [round(ratio, 2)]})
